CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY, keeper INTEGER NOT NULL DEFAULT 0, bless_until INTEGER NOT NULL DEFAULT 0, paid_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pays (charge TEXT PRIMARY KEY, user_id INTEGER NOT NULL, item TEXT NOT NULL, stars INTEGER NOT NULL, at INTEGER NOT NULL, given INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS pays_user ON pays (user_id, given);
CREATE TABLE IF NOT EXISTS saves (id INTEGER PRIMARY KEY, data TEXT NOT NULL, saved_at INTEGER NOT NULL, name TEXT NOT NULL DEFAULT '', score INTEGER NOT NULL DEFAULT 0, score_at INTEGER NOT NULL DEFAULT 0, first TEXT NOT NULL DEFAULT '', photo TEXT NOT NULL DEFAULT '', hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS saves_top ON saves (hidden, score DESC, score_at, id);
